/// Exceptions thrown by the data layer when something goes wrong while
/// reading from or writing to the in-memory data source.
class CacheException implements Exception {
  final String message;
  const CacheException(this.message);

  @override
  String toString() => 'CacheException: $message';
}

import 'package:equatable/equatable.dart';

/// Base class for all failures that can be surfaced to the domain and
/// presentation layers. Failures are the "safe", serializable counterpart
/// to the exceptions thrown by the data layer.
abstract class Failure extends Equatable {
  final String message;
  const Failure(this.message);

  @override
  List<Object?> get props => [message];
}

class CacheFailure extends Failure {
  const CacheFailure(super.message);
}

class UnexpectedFailure extends Failure {
  const UnexpectedFailure(super.message);
}

import 'error/failures.dart';

/// A minimal Either-like type used instead of pulling in a third-party
/// functional programming package. A [Result] is either a [Success]
/// carrying a value of type [T], or an [Error] carrying a [Failure].
sealed class Result<T> {
  const Result();
}

class Success<T> extends Result<T> {
  final T data;
  const Success(this.data);
}

class Error<T> extends Result<T> {
  final Failure failure;
  const Error(this.failure);
}

