/// A simple in-memory "database" that stands in for a real local cache
/// (e.g. sqlite, Hive, shared_preferences) or a remote API. Data does not
/// survive app restarts.
class TaskLocalDataSource {
  final List<TaskModel> _tasks = [
    TaskModel(
      id: 't1',
      title: 'Buy groceries',
      description: 'Milk, eggs, bread, and coffee',
      isCompleted: false,
      createdAt: DateTime(2026, 1, 3),
    ),
    TaskModel(
      id: 't2',
      title: 'Finish quarterly report',
      description: 'Draft the Q1 numbers for the team meeting',
      isCompleted: false,
      createdAt: DateTime(2026, 1, 5),
    ),
    TaskModel(
      id: 't3',
      title: 'Book dentist appointment',
      description: 'Call the clinic before Friday',
      isCompleted: true,
      createdAt: DateTime(2026, 1, 2),
    ),
    TaskModel(
      id: 't4',
      title: 'Renew gym membership',
      description: 'Membership expires at the end of the month',
      isCompleted: false,
      createdAt: DateTime(2026, 1, 6),
    ),
    TaskModel(
      id: 't5',
      title: 'Read "Deep Work"',
      description: 'Finish the last two chapters',
      isCompleted: true,
      createdAt: DateTime(2026, 1, 1),
    ),
  ];

  /// Returns every task currently stored in memory.
  Future<List<TaskModel>> getTasks() async {
    await Future.delayed(const Duration(milliseconds: 400));

    return List.unmodifiable(_tasks);
  }

  Future<void> deleteTask(String id) async {
    await Future.delayed(const Duration(milliseconds: 150));
    _tasks.removeWhere((task) => task.id == id);
  }

  Future<void> toggleTaskCompletion(String id) async {
    await Future.delayed(const Duration(milliseconds: 150));

    final index = _tasks.indexWhere((task) => task.id == id);
    if (index == -1) {
      throw CacheException('Task with id "$id" was not found');
    }

    _tasks[index] = _tasks[index].copyWith(
      isCompleted: !_tasks[index].isCompleted,
    );
  }
}

import '../../domain/entities/task.dart';

class TaskModel extends Task {
  const TaskModel({
    required super.id,
    required super.title,
    required super.description,
    required super.isCompleted,
    required super.createdAt,
  });

  factory TaskModel.fromJson(Map<String, dynamic> json) {
    return TaskModel(
      id: json['id'] as String,
      title: json['title'] as String,
      description: json['description'] as String,
      isCompleted: json['isCompleted'] as bool,
      createdAt: DateTime.parse(json['createdAt'] as String),
    );
  }

  Map<String, dynamic> toJson() {
    return {
      'id': id,
      'title': title,
      'description': description,
      'isCompleted': isCompleted,
      'createdAt': createdAt.toIso8601String(),
    };
  }

  factory TaskModel.fromEntity(Task task) {
    return TaskModel(
      id: task.id,
      title: task.title,
      description: task.description,
      isCompleted: task.isCompleted,
      createdAt: task.createdAt,
    );
  }

  Task toEntity() {
    return Task(
      id: id,
      title: title,
      description: description,
      isCompleted: isCompleted,
      createdAt: createdAt,
    );
  }

  @override
  TaskModel copyWith({
    String? id,
    String? title,
    String? description,
    bool? isCompleted,
    DateTime? createdAt,
  }) {
    return TaskModel(
      id: id ?? this.id,
      title: title ?? this.title,
      description: description ?? this.description,
      isCompleted: isCompleted ?? this.isCompleted,
      createdAt: createdAt ?? this.createdAt,
    );
  }
}

