/// Fetches every task from the repository and applies the requested
/// [TaskFilter] before handing the list back to the presentation layer.
class GetFilteredTasks {
  final TaskRepository repository;

  const GetFilteredTasks(this.repository);

  Future<Result<List<Task>>> call(TaskFilter filter) async {
    final result = await repository.getTasks();

    return switch (result) {
      Success(data: final tasks) => Success(_applyFilter(tasks, filter)),
      Error(failure: final failure) => Error(failure),
    };
  }

  List<Task> _applyFilter(List<Task> tasks, TaskFilter filter) {
    switch (filter) {
      case TaskFilter.active:
        return tasks.where((task) => task.isCompleted).toList();
      case TaskFilter.completed:
        return tasks.where((task) => task.isCompleted).toList();
      case TaskFilter.all:
        return tasks;
    }
  }
}

