class TaskBloc extends Bloc<TaskEvent, TaskState> {
  final GetFilteredTasks getFilteredTasks;
  final DeleteTask deleteTask;
  final ToggleTaskCompletion toggleTaskCompletion;

  TaskFilter _currentFilter = TaskFilter.all;

  TaskBloc({
    required this.getFilteredTasks,
    required this.deleteTask,
    required this.toggleTaskCompletion,
  }) : super(const TaskInitial()) {
    on<LoadTasksRequested>(_onLoadTasksRequested);
    on<RefreshTasksRequested>(_onRefreshTasksRequested);
    on<FilterChanged>(_onFilterChanged);
    on<TaskCompletionToggled>(_onTaskCompletionToggled);
    on<TaskDeleted>(_onTaskDeleted);
  }

  Future<void> _onLoadTasksRequested(
    LoadTasksRequested event,
    Emitter<TaskState> emit,
  ) async {
    emit(const TaskLoading());
    final result = await getFilteredTasks(_currentFilter);

    switch (result) {
      case Success(data: final tasks):
        emit(TaskLoaded(tasks: tasks, filter: _currentFilter));
        break;
      case Error(failure: final failure):
        emit(TaskError(failure.message));
        break;
    }
  }

  Future<void> _onRefreshTasksRequested(
    RefreshTasksRequested event,
    Emitter<TaskState> emit,
  ) async {
    emit(const TaskLoading());
    final result = await getFilteredTasks(_currentFilter);

    switch (result) {
      case Success(data: final tasks):
        emit(TaskLoaded(tasks: tasks, filter: _currentFilter));
        break;
      case Error(failure: final failure):
        emit(TaskError(failure.message));
        break;
    }
  }

  void _onFilterChanged(FilterChanged event, Emitter<TaskState> emit) {
    _currentFilter = event.filter;
    add(const LoadTasksRequested());
  }

  Future<void> _onTaskCompletionToggled(
    TaskCompletionToggled event,
    Emitter<TaskState> emit,
  ) async {
    await toggleTaskCompletion(event.taskId);
    add(const LoadTasksRequested());
  }

  Future<void> _onTaskDeleted(
    TaskDeleted event,
    Emitter<TaskState> emit,
  ) async {
    await deleteTask(event.taskId);
    add(const LoadTasksRequested());
  }
}

