sealed class TaskEvent extends Equatable {
  const TaskEvent();

  @override
  List<Object?> get props => [];
}

/// Loads (or reloads) the task list from scratch. Used for the initial
/// load, after a filter change, and after a task is toggled or deleted.
class LoadTasksRequested extends TaskEvent {
  const LoadTasksRequested();
}

/// Triggered by the pull-to-refresh gesture / refresh button.
class RefreshTasksRequested extends TaskEvent {
  const RefreshTasksRequested();
}

class FilterChanged extends TaskEvent {
  final TaskFilter filter;

  const FilterChanged(this.filter);

  @override
  List<Object?> get props => [filter];
}

class TaskCompletionToggled extends TaskEvent {
  final String taskId;

  const TaskCompletionToggled(this.taskId);

  @override
  List<Object?> get props => [taskId];
}

class TaskDeleted extends TaskEvent {
  final String taskId;

  const TaskDeleted(this.taskId);

  @override
  List<Object?> get props => [taskId];
}

