class TaskListPage extends StatelessWidget {
  const TaskListPage({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('PatchPilot Tasks'),
        actions: [
          IconButton(
            icon: const Icon(Icons.refresh),
            tooltip: 'Refresh',
            onPressed: () {
              context.read<TaskBloc>().add(const RefreshTasksRequested());
            },
          ),
        ],
      ),
      body: BlocBuilder<TaskBloc, TaskState>(
        builder: (context, state) {
          return switch (state) {
            TaskInitial() || TaskLoading() => const Center(
                child: CircularProgressIndicator(),
              ),
            TaskLoaded(tasks: final tasks, filter: final filter) => Column(
                children: [
                  Padding(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 16,
                      vertical: 8,
                    ),
                    child: FilterChips(
                      selected: filter,
                      onChanged: (newFilter) {
                        context.read<TaskBloc>().add(FilterChanged(newFilter));
                      },
                    ),
                  ),
                  Expanded(
                    child: tasks.isEmpty
                        ? const Center(child: Text('No tasks yet'))
                        : ListView.builder(
                            itemCount: tasks.length,
                            itemBuilder: (context, index) {
                              final task = tasks[index];
                              return TaskTile(
                                task: task,
                                onToggle: () {
                                  context.read<TaskBloc>().add(
                                        TaskCompletionToggled(task.id),
                                      );
                                },
                                onDelete: () {
                                  context
                                      .read<TaskBloc>()
                                      .add(TaskDeleted(task.id));
                                },
                              );
                            },
                          ),
                  ),
                ],
              ),
            TaskError(message: final message) => Center(
                child: Padding(
                  padding: const EdgeInsets.all(24),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      const Icon(Icons.error_outline, size: 40),
                      const SizedBox(height: 12),
                      Text(
                        'Failed to load tasks',
                        style: Theme.of(context).textTheme.titleMedium,
                        textAlign: TextAlign.center,
                      ),
                      const SizedBox(height: 4),
                      Text(
                        message,
                        textAlign: TextAlign.center,
                        style: Theme.of(context).textTheme.bodySmall,
                      ),
                      const SizedBox(height: 16),
                      ElevatedButton(
                        onPressed: () {
                          context
                              .read<TaskBloc>()
                              .add(const LoadTasksRequested());
                        },
                        child: const Text('Retry'),
                      ),
                    ],
                  ),
                ),
              ),
          };
        },
      ),
    );
  }
}

