import 'package:flutter_test/flutter_test.dart';
import 'package:patchpilot_diagnosis_demo/data/datasources/task_local_data_source.dart';

void main() {
  group('TaskLocalDataSource', () {
    test('getTasks returns the seeded tasks', () async {
      final dataSource = TaskLocalDataSource();

      final tasks = await dataSource.getTasks();

      expect(tasks, isNotEmpty);
    });

    test('deleteTask removes a task by id', () async {
      final dataSource = TaskLocalDataSource();
      final before = await dataSource.getTasks();

      await dataSource.deleteTask(before.first.id);
      final after = await dataSource.getTasks();

      expect(after.length, before.length - 1);
    });

    test('toggleTaskCompletion flips the isCompleted flag', () async {
      final dataSource = TaskLocalDataSource();
      final before = await dataSource.getTasks();
      final target = before.first;

      await dataSource.toggleTaskCompletion(target.id);
      final after = await dataSource.getTasks();
      final updated = after.firstWhere((t) => t.id == target.id);

      expect(updated.isCompleted, !target.isCompleted);
    });
  });
}

