class _MockTaskLocalDataSource extends Mock implements TaskLocalDataSource {}

void main() {
  late _MockTaskLocalDataSource dataSource;
  late TaskRepositoryImpl repository;

  setUpAll(() {
    registerFallbackValue('fallback-id');
  });

  setUp(() {
    dataSource = _MockTaskLocalDataSource();
    repository = TaskRepositoryImpl(dataSource);
  });

  group('getTasks', () {
    test(
      'returns Success with mapped entities when the data source succeeds',
      () async {
        final models = [
          TaskModel(
            id: '1',
            title: 'Task 1',
            description: 'desc',
            isCompleted: false,
            createdAt: DateTime(2026, 1, 1),
          ),
        ];
        when(() => dataSource.getTasks()).thenAnswer((_) async => models);

        final result = await repository.getTasks();

        expect(result, isA<Success<List<Task>>>());
        expect((result as Success<List<Task>>).data.first.id, '1');
      },
    );

    test('returns Error when the data source throws a CacheException',
        () async {
      when(() => dataSource.getTasks())
          .thenThrow(const CacheException('boom'));

      final result = await repository.getTasks();

      expect(result, isA<Error<List<Task>>>());
    });
  });

  group('deleteTask', () {
    test('returns Success after delegating to the data source', () async {
      when(() => dataSource.deleteTask(any())).thenAnswer((_) async {});

      final result = await repository.deleteTask('1');

      expect(result, isA<Success<void>>());
      verify(() => dataSource.deleteTask('1')).called(1);
    });
  });

  group('toggleTaskCompletion', () {
    test('returns Success after delegating to the data source', () async {
      when(() => dataSource.toggleTaskCompletion(any()))
          .thenAnswer((_) async {});

      final result = await repository.toggleTaskCompletion('1');

      expect(result, isA<Success<void>>());
      verify(() => dataSource.toggleTaskCompletion('1')).called(1);
    });
  });
}

