void main() {
  final tasks = [
    Task(
      id: '1',
      title: 'Task 1',
      description: 'desc',
      isCompleted: false,
      createdAt: DateTime(2026, 1, 1),
    ),
    Task(
      id: '2',
      title: 'Task 2',
      description: 'desc',
      isCompleted: true,
      createdAt: DateTime(2026, 1, 2),
    ),
    Task(
      id: '3',
      title: 'Task 3',
      description: 'desc',
      isCompleted: true,
      createdAt: DateTime(2026, 1, 3),
    ),
  ];

  group('GetFilteredTasks', () {
    test('returns every task when filter is TaskFilter.all', () async {
      final useCase = GetFilteredTasks(_FakeTaskRepository(tasks));

      final result = await useCase(TaskFilter.all);

      expect(result, isA<Success<List<Task>>>());
      expect((result as Success<List<Task>>).data, hasLength(3));
    });

    test(
      'returns only completed tasks when filter is TaskFilter.completed',
      () async {
        final useCase = GetFilteredTasks(_FakeTaskRepository(tasks));

        final result = await useCase(TaskFilter.completed);

        final data = (result as Success<List<Task>>).data;
        expect(data, hasLength(2));
        expect(data.every((task) => task.isCompleted), isTrue);
      },
    );

    test('propagates a failure from the repository', () async {
      final useCase = GetFilteredTasks(_FailingRepository());

      final result = await useCase(TaskFilter.all);

      expect(result, isA<Error<List<Task>>>());
    });
  });
}

