import 'package:patchpilot_diagnosis_demo/domain/repositories/task_repository.dart';
import 'package:patchpilot_diagnosis_demo/domain/usecases/delete_task.dart';
import 'package:patchpilot_diagnosis_demo/domain/usecases/get_filtered_tasks.dart';
import 'package:patchpilot_diagnosis_demo/domain/usecases/toggle_task_completion.dart';
import 'package:patchpilot_diagnosis_demo/presentation/bloc/task_bloc.dart';
import 'package:patchpilot_diagnosis_demo/presentation/bloc/task_event.dart';
import 'package:patchpilot_diagnosis_demo/presentation/bloc/task_state.dart';

class _FakeTaskRepository implements TaskRepository {
  List<Task> tasks;

  _FakeTaskRepository(this.tasks);

  @override
  Future<Result<List<Task>>> getTasks() async => Success(List.of(tasks));

  @override
  Future<Result<void>> deleteTask(String id) async {
    tasks = tasks.where((t) => t.id != id).toList();
    return const Success(null);
  }

  @override
  Future<Result<void>> toggleTaskCompletion(String id) async {
    tasks = tasks
        .map((t) => t.id == id ? t.copyWith(isCompleted: !t.isCompleted) : t)
        .toList();
    return const Success(null);
  }
}

class _FailingRepository implements TaskRepository {
  @override
  Future<Result<List<Task>>> getTasks() async =>
      const Error(CacheFailure('boom'));

  @override
  Future<Result<void>> deleteTask(String id) async =>
      const Error(CacheFailure('boom'));

  @override
  Future<Result<void>> toggleTaskCompletion(String id) async =>
      const Error(CacheFailure('boom'));
}

void main() {
  final seedTasks = [
    Task(
      id: '1',
      title: 'Task 1',
      description: 'desc',
      isCompleted: false,
      createdAt: DateTime(2026, 1, 1),
    ),
    Task(
      id: '2',
      title: 'Task 2',
      description: 'desc',
      isCompleted: true,
      createdAt: DateTime(2026, 1, 2),
    ),
  ];

  TaskBloc buildBloc() {
    final repository = _FakeTaskRepository(List.of(seedTasks));
    return TaskBloc(
      getFilteredTasks: GetFilteredTasks(repository),
      deleteTask: DeleteTask(repository),
      toggleTaskCompletion: ToggleTaskCompletion(repository),
    );
  }

  blocTest<TaskBloc, TaskState>(
    'emits [TaskLoading, TaskLoaded] when LoadTasksRequested succeeds',
    build: buildBloc,
    act: (bloc) => bloc.add(const LoadTasksRequested()),
    expect: () => [
      const TaskLoading(),
      isA<TaskLoaded>()
          .having((state) => state.tasks.length, 'tasks.length', 2)
          .having((state) => state.filter, 'filter', TaskFilter.all),
    ],
  );

  blocTest<TaskBloc, TaskState>(
    'reloads the list after a task is deleted',
    build: buildBloc,
    act: (bloc) => bloc.add(const TaskDeleted('1')),
    expect: () => [
      const TaskLoading(),
      isA<TaskLoaded>().having((s) => s.tasks.length, 'tasks.length', 1),
    ],
  );

  blocTest<TaskBloc, TaskState>(
    'emits TaskError when the repository returns a failure',
    build: () => TaskBloc(
      getFilteredTasks: GetFilteredTasks(_FailingRepository()),
      deleteTask: DeleteTask(_FailingRepository()),
      toggleTaskCompletion: ToggleTaskCompletion(_FailingRepository()),
    ),
    act: (bloc) => bloc.add(const LoadTasksRequested()),
    expect: () => [
      const TaskLoading(),
      isA<TaskError>(),
    ],
  );
}
